# Every agent, in one file, on one platform:
#   shared gateway · registry tools · scoped memory
#   three-surface guardrails · full tracing · CI evals
name: support-triage
version: 3.2.0
model:   { deployment: my-gpt4o, temperature: 0.2 }
tools:   [ticket.search, ticket.reply{hitl}, kb.lookup]
memory:  [conversation{ttl:90d}, user-profile{pii:masked}]
guardrails: { input: standard, output: standard, action: strict }
budget:  { max_steps: 12, max_cost_usd: 0.35, deadline_s: 240 }
evals:   { golden_set: evals/triage.jsonl, min_success: 0.92 }

# New agents: copy, diff, review, deploy — days, not months.
